import de.backendlab.experiments.Experiments;import java.util.concurrent.*;import java.net.http.*;
public class IoChecks {public static void main(String[] args){var pool=Executors.newFixedThreadPool(4);try{var client=HttpClient.newHttpClient();for(String mode:new String[]{"blocking","sequential-async","concurrent"}){var result=Experiments.io(client,args[0],mode,pool).toCompletableFuture().join();if(result.size()!=3||!result.get(0).contains("product")||!result.get(2).contains("pricing"))throw new AssertionError(mode);}System.out.println("PASS: three real HTTP I/O strategies against local mock");}finally{pool.shutdownNow();}}}
